///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search_detail
 * @author Inswave
 * @date 2026. 09. 29
 * @param integSrchNo
 * @returns
 * @hidden N
*/
scwin.search_detail = function (integSrchNo) {
    /* sdd-asis-lifecycle:begin search_detail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const curIntegSrchNo = $('#integSrchNo').val();
    if (curIntegSrchNo === integSrchNo) {
        return;
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "searchIntegsrchList") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#integSrchNo').val(integSrchNo);
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.regBzExpl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.regBzExpl = function () {
    /* sdd-asis-lifecycle:begin regBzExpl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('bzExplContn', a) : console.warn('[sdd] hiddenStore 부재: bzExplContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertBzExpl") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
    /* sdd-asis-lifecycle:end */
};


