    /* sdd-asis-lifecycle:begin regMcc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const a = DEXT5.getBodyValue("dext5editor3");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mccContn', a) : console.warn('[sdd] hiddenStore 부재: mccContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertMcc") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
    /* sdd-asis-lifecycle:end */
};


