*/
scwin.regMktactRsn = function () {
    /* sdd-asis-lifecycle:begin regMktactRsn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const a = DEXT5.getBodyValue("dext5editor2");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mktactRsnContn', a) : console.warn('[sdd] hiddenStore 부재: mktactRsnContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertMktactRsn") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
