};


/**
 * @method
 * @name scwin.regAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.regAll = function () {
    /* sdd-asis-lifecycle:begin regAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let a = DEXT5.getBodyValue("dext5editor2");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mktactRsnContn', a) : console.warn('[sdd] hiddenStore 부재: mktactRsnContn'));
    a = DEXT5.getBodyValue("dext5editor3");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('mccContn', a) : console.warn('[sdd] hiddenStore 부재: mccContn'));
    a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('bzExplContn', a) : console.warn('[sdd] hiddenStore 부재: bzExplContn'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "insertAll") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#headerKeywrdForm')[0].submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dext_editor_loaded_event
 * @author Inswave
 * @date 2026. 09. 29
 * @param editor
 * @returns
 * @hidden N
*/
scwin.dext_editor_loaded_event = function (editor) {
    /* sdd-asis-lifecycle:begin dext_editor_loaded_event — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (editor.ID === "dext5editor1") {
        DEXT5.setBodyValue(dma_hiddenStore.get("bzExplContn"), editor.ID);
    } else {
        if (editor.ID === "dext5editor3") {
            DEXT5.setBodyValue(dma_hiddenStore.get("mccContn"), editor.ID);
            setTimeout(function(){ scrollTo(0,0); }, 500);
        } else {
            if (editor.ID === "dext5editor2") {
                DEXT5.setBodyValue(dma_hiddenStore.get("mktactRsnContn"), editor.ID);
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
